import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { Item, ItemActions, ItemContent, ItemGroup, ItemTitle } from "@/registry/erbium/ui/item";
import { RelativeTime, RelativeTimeProvider } from "@/registry/erbium/ui/relative-time";
import { DAY, HOUR, useDemoClock } from "./use-demo-clock";

export default function RelativeTimeExample() {
  const now = useDemoClock();

  const events = [
    { name: "Comment added", date: now },
    { name: "Build finished", date: now - 3 * HOUR },
    { name: "Workspace created", date: now - 740 * DAY },
    { name: "Review due", date: now + 4 * DAY },
    { name: "Plan renews", date: now + 65 * DAY },
  ];

  return (
    <RelativeTimeProvider locale="en">
      <ItemGroup className="w-80">
        {events.map((event) => (
          <Item key={event.name} size="sm">
            <ItemContent>
              <ItemTitle>{event.name}</ItemTitle>
            </ItemContent>
            <ItemActions>
              <RelativeTime date={event.date} className="text-muted-foreground" />
            </ItemActions>
          </Item>
        ))}
      </ItemGroup>
    </RelativeTimeProvider>
  );
}

import { useState, useSyncExternalStore } from "react";

/*
 * Dates for these examples, measured from when they appear. In an app the dates come from your
 * data, and this is not needed.
 */

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/** A fixed moment for server rendering, so the server and the browser write the same HTML. */
const reference = Date.UTC(2026, 0, 15, 12);

const subscribe = () => () => {
  // Whether the page has hydrated never changes back.
};

const useDemoClock = () => {
  // oxlint-disable-next-line react/hook-use-state -- the time is read once, when the example appears, and never replaced.
  const [appeared] = useState(() => Date.now());

  return useSyncExternalStore(
    subscribe,
    () => appeared,
    () => reference,
  );
};

export { DAY, HOUR, MINUTE, useDemoClock };

