import { RelativeTime } from "@/registry/erbium/ui/relative-time";
import type { RelativeTimeProps } from "@/registry/erbium/ui/relative-time";
import { DAY, HOUR, MINUTE, useDemoClock } from "../examples/use-demo-clock";

/** How far from now each choice is. */
export const distances = {
  "-2 years": -740 * DAY,
  "-3 hours": -3 * HOUR,
  "-26 hours": -26 * HOUR,
  now: 0,
  "+5 minutes": 5 * MINUTE,
  "+4 days": 4 * DAY,
  "+2 months": 65 * DAY,
};

type PlaygroundProps = Pick<
  RelativeTimeProps,
  "format" | "formatStyle" | "locale" | "maxUnits" | "numeric"
> & { distance: keyof typeof distances };

export const defaultProps = {
  distance: "-3 hours",
  format: "relative",
  formatStyle: "long",
  locale: "en",
  maxUnits: 1,
  numeric: "auto",
} satisfies PlaygroundProps;

export default function RelativeTimePlaygroundExample({
  distance,
  ...props
}: PlaygroundProps = defaultProps) {
  const now = useDemoClock();

  return <RelativeTime date={now + distances[distance]} className="text-title" {...props} />;
}

import { DirectionProvider } from "@/registry/erbium/ui/direction";
import { Item, ItemActions, ItemContent, ItemGroup, ItemTitle } from "@/registry/erbium/ui/item";
import { RelativeTimeCard, RelativeTimeProvider } from "@/registry/erbium/ui/relative-time";
import { DAY, HOUR, MINUTE, useDemoClock } from "../examples/use-demo-clock";

export default function RelativeTimeRtlExample() {
  const now = useDemoClock();

  const events = [
    { name: "دیدگاه تازه", date: now - 5 * MINUTE },
    { name: "ساخت پایان یافت", date: now - 3 * HOUR },
    { name: "مهلت بازبینی", date: now + 4 * DAY },
  ];

  return (
    // The app's direction and language. Pass the same locale to the times.
    <DirectionProvider direction="rtl">
      <RelativeTimeProvider locale="fa-IR">
        <div dir="rtl" lang="fa" className="w-80">
          <ItemGroup>
            {events.map((event) => (
              <Item key={event.name} size="sm">
                <ItemContent>
                  <ItemTitle>{event.name}</ItemTitle>
                </ItemContent>
                <ItemActions>
                  <RelativeTimeCard date={event.date} />
                </ItemActions>
              </Item>
            ))}
          </ItemGroup>
        </div>
      </RelativeTimeProvider>
    </DirectionProvider>
  );
}

import { Badge } from "@/registry/erbium/ui/badge";
import { RelativeTime, RelativeTimeProvider } from "@/registry/erbium/ui/relative-time";
import { DAY, useDemoClock } from "../examples/use-demo-clock";

export default function RelativeTimeStateExample() {
  const now = useDemoClock();
  const deadlines = [now - 2 * DAY, now + DAY, now + 12 * DAY];

  return (
    <RelativeTimeProvider locale="en">
      <div className="flex flex-wrap justify-center gap-related">
        {deadlines.map((date) => (
          // `render` swaps the element, and `children` can write from the state.
          <RelativeTime
            key={date}
            date={date}
            render={(props, state) => (
              <Badge
                variant={state.tense === "past" ? "error" : "secondary"}
                render={<time />}
                {...props}
              />
            )}
          >
            {(state) => (state.tense === "past" ? `Overdue, ${state.text}` : `Due ${state.text}`)}
          </RelativeTime>
        ))}
      </div>
    </RelativeTimeProvider>
  );
}

import { RelativeTime, RelativeTimeProvider } from "@/registry/erbium/ui/relative-time";
import { DAY, HOUR, useDemoClock } from "../examples/use-demo-clock";

/** Seven days, in seconds. */
const week = 7 * 24 * 60 * 60;

export default function RelativeTimeThresholdExample() {
  const now = useDemoClock();
  const dates = [now - 2 * HOUR, now - 6 * DAY, now - 30 * DAY, now + 90 * DAY];

  return (
    <RelativeTimeProvider locale="en" threshold={week}>
      <ul className="flex flex-col gap-1 text-caption">
        {dates.map((date) => (
          <li key={date}>
            <RelativeTime date={date} />
          </li>
        ))}
      </ul>
    </RelativeTimeProvider>
  );
}

import { RelativeTime } from "@/registry/erbium/ui/relative-time";
import type { RelativeTimeProps } from "@/registry/erbium/ui/relative-time";
import { DAY, HOUR, useDemoClock } from "../examples/use-demo-clock";

type Labels = NonNullable<RelativeTimeProps["labels"]>;

// Define labels once, outside render. Each function receives a duration in the same language.
const english: Labels = {
  future: (duration) => `${duration} later`,
  now: "this moment",
  past: (duration) => `${duration} earlier`,
};

const persian: Labels = {
  future: (duration) => `${duration} دیگر`,
  now: "همین حالا",
  past: (duration) => `${duration} پیش`,
};

export default function RelativeTimeWordingExample() {
  const now = useDemoClock();
  const dates = [now - 3 * DAY - 4 * HOUR, now, now + 65 * DAY];

  return (
    <div className="flex flex-wrap justify-center gap-12 text-caption">
      <div className="flex flex-col gap-1">
        {dates.map((date) => (
          <RelativeTime key={date} date={date} locale="en" labels={english} />
        ))}
      </div>
      {/* Two units need labels outside English; without them the time uses one unit. */}
      <div dir="rtl" className="flex flex-col gap-1">
        {dates.map((date) => (
          <RelativeTime key={date} date={date} locale="fa-IR" labels={persian} maxUnits={2} />
        ))}
      </div>
    </div>
  );
}
